class Solution:
    def maxDistance(self, s: str, k: int) -> int:
        n = s_cnt = e = w = 0
        ans = 0
        for c in s:
            if c == 'N':
                n += 1
            elif c == 'S':
                s_cnt += 1
            elif c == 'E':
                e += 1
            else:
                w += 1
            base = abs(n - s_cnt) + abs(e - w)
            mismatch = min(n, s_cnt) + min(e, w)
            ans = max(ans, base + 2 * min(k, mismatch))
        return ans
