class Solution:
    def numberOfComponents(self, properties: List[List[int]], k: int) -> int:
        n = len(properties)

        # Build a bitmask of distinct values for each row
        masks = []
        for row in properties:
            mask = 0
            for v in row:
                mask |= 1 << v
            masks.append(mask)

        parent = list(range(n))

        def find(x: int) -> int:
            while parent[x] != x:
                parent[x] = parent[parent[x]]
                x = parent[x]
            return x

        def union(a: int, b: int) -> None:
            ra, rb = find(a), find(b)
            if ra != rb:
                parent[ra] = rb

        # Connect pairs whose distinct intersection size is at least k
        for i in range(n):
            for j in range(i + 1, n):
                if bin(masks[i] & masks[j]).count('1') >= k:
                    union(i, j)

        return len({find(i) for i in range(n)})
