class Solution:
    def sortMatrix(self, grid: List[List[int]]) -> List[List[int]]:
        n = len(grid)
        # Bottom-left triangle diagonals (including middle): start at (i, 0)
        for i in range(n):
            diag = [grid[i + k][k] for k in range(n - i)]
            diag.sort(reverse=True)
            for k in range(n - i):
                grid[i + k][k] = diag[k]
        # Top-right triangle diagonals: start at (0, j)
        for j in range(1, n):
            diag = [grid[k][j + k] for k in range(n - j)]
            diag.sort()
            for k in range(n - j):
                grid[k][j + k] = diag[k]
        return grid
