class Solution:
    def minZeroArray(self, nums: List[int], queries: List[List[int]]) -> int:
        n = len(nums)
        need = [i for i in range(n) if nums[i] > 0]
        if not need:
            return 0
        MASK = (1 << 1001) - 1
        # dp[i]: bitset of achievable decrement sums at index i using queries so far
        dp = [1] * n  # sum 0 achievable
        for k, (l, r, val) in enumerate(queries, start=1):
            for i in range(l, r + 1):
                dp[i] = (dp[i] | (dp[i] << val)) & MASK
            if all((dp[i] >> nums[i]) & 1 for i in need):
                return k
        return -1
