class Solution:
    def assignElements(self, groups: List[int], elements: List[int]) -> List[int]:
        max_val = max(groups)
        assign = [-1] * (max_val + 1)
        seen = set()
        for j, v in enumerate(elements):
            if v > max_val or v in seen:
                continue
            seen.add(v)
            for m in range(v, max_val + 1, v):
                if assign[m] == -1:
                    assign[m] = j
        return [assign[g] for g in groups]
